class BillingJanitor:
    RETENTION_DAYS = 900

    def run(self, session, today):
        cutoff = today - timedelta(days=self.RETENTION_DAYS)
        session.query(Invoice).filter(Invoice.created_at < cutoff).delete()

class BillingRetention:
    def __init__(self, session):
        self.session = session

    def purge_expired(self):
        self.session.execute(
            "DELETE FROM invoices WHERE issued_at < now() - interval '2190 days'"
        )
        self.session.commit()

def reveal_key(key_id, repo):
